loadstring("--// Services\nlocal Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal RunService = game:GetService(\"RunService\")\nlocal BulletEvent = ReplicatedStorage.Events.BulletEvent\n\nlocal localPlayer = Players.LocalPlayer\nlocal playerGui = localPlayer:WaitForChild(\"PlayerGui\")\n\n--// GUI Setup\nlocal screenGui = Instance.new(\"ScreenGui\")\nscreenGui.Name = \"PlayerToolsGui\"\nscreenGui.ResetOnSpawn = false\nscreenGui.Parent = playerGui\n\n-- Main GUI Frame\nlocal mainFrame = Instance.new(\"Frame\")\nmainFrame.Size = UDim2.new(0, 200, 0, 350)\nmainFrame.Position = UDim2.new(0, 20, 0.5, -175)\nmainFrame.BackgroundColor3 = Color3.fromRGB(30, 30, 30)\nmainFrame.BorderSizePixel = 0\nmainFrame.Parent = screenGui\n\nlocal stroke = Instance.new(\"UIStroke\")\nstroke.Thickness = 2\nstroke.Color = Color3.fromRGB(255, 255, 255)\nstroke.Parent = mainFrame\n\nlocal title = Instance.new(\"TextLabel\")\ntitle.Text = \"Player List\"\ntitle.Size = UDim2.new(1, 0, 0, 30)\ntitle.BackgroundTransparency = 1\ntitle.TextColor3 = Color3.fromRGB(255, 255, 255)\ntitle.Font = Enum.Font.SourceSansBold\ntitle.TextSize = 20\ntitle.Parent = mainFrame\n\nlocal scroll = Instance.new(\"ScrollingFrame\")\nscroll.Size = UDim2.new(1, 0, 1, -30)\nscroll.Position = UDim2.new(0, 0, 0, 30)\nscroll.CanvasSize = UDim2.new(0, 0, 0, 0)\nscroll.BackgroundColor3 = Color3.fromRGB(40, 40, 40)\nscroll.BorderSizePixel = 0\nscroll.ScrollBarThickness = 6\nscroll.Parent = mainFrame\n\nlocal layout = Instance.new(\"UIListLayout\")\nlayout.SortOrder = Enum.SortOrder.LayoutOrder\nlayout.Padding = UDim.new(0, 4)\nlayout.Parent = scroll\n\n-- Right Panel Frame\nlocal controlPanel = Instance.new(\"Frame\")\ncontrolPanel.Size = UDim2.new(0, 200, 0, 220)\ncontrolPanel.Position = UDim2.new(0, 230, 0.5, -110)\ncontrolPanel.BackgroundColor3 = Color3.fromRGB(20, 20, 20)\ncontrolPanel.BorderSizePixel = 0\ncontrolPanel.Parent = screenGui\n\nlocal panelStroke = Instance.new(\"UIStroke\")\npanelStroke.Thickness = 2\npanelStroke.Color = Color3.fromRGB(255, 255, 255)\npanelStroke.Parent = controlPanel\n\n-- Player Name TextBox\nlocal nameBox = Instance.new(\"TextBox\")\nnameBox.PlaceholderText = \"Enter player name\"\nnameBox.Size = UDim2.new(1, -20, 0, 30)\nnameBox.Position = UDim2.new(0, 10, 0, 10)\nnameBox.Font = Enum.Font.SourceSans\nnameBox.TextSize = 18\nnameBox.TextColor3 = Color3.new(1,1,1)\nnameBox.BackgroundColor3 = Color3.fromRGB(50, 50, 50)\nnameBox.ClearTextOnFocus = false\nnameBox.Parent = controlPanel\n\n-- Kill Player Button\nlocal killButton = Instance.new(\"TextButton\")\nkillButton.Text = \"Kill Player\"\nkillButton.Size = UDim2.new(1, -20, 0, 30)\nkillButton.Position = UDim2.new(0, 10, 0, 50)\nkillButton.BackgroundColor3 = Color3.fromRGB(100, 30, 30)\nkillButton.TextColor3 = Color3.new(1, 1, 1)\nkillButton.Font = Enum.Font.SourceSansBold\nkillButton.TextSize = 18\nkillButton.Parent = controlPanel\n\n-- Kill All Button\nlocal killAllButton = Instance.new(\"TextButton\")\nkillAllButton.Text = \"Kill All\"\nkillAllButton.Size = UDim2.new(1, -20, 0, 30)\nkillAllButton.Position = UDim2.new(0, 10, 0, 90)\nkillAllButton.BackgroundColor3 = Color3.fromRGB(30, 100, 30)\nkillAllButton.TextColor3 = Color3.new(1, 1, 1)\nkillAllButton.Font = Enum.Font.SourceSansBold\nkillAllButton.TextSize = 18\nkillAllButton.Parent = controlPanel\n\n-- Auto Kill Toggle Button\nlocal autoKillButton = Instance.new(\"TextButton\")\nautoKillButton.Text = \"Auto Kill: OFF\"\nautoKillButton.Size = UDim2.new(1, -20, 0, 30)\nautoKillButton.Position = UDim2.new(0, 10, 0, 130)\nautoKillButton.BackgroundColor3 = Color3.fromRGB(60, 30, 30)\nautoKillButton.TextColor3 = Color3.new(1, 1, 1)\nautoKillButton.Font = Enum.Font.SourceSansBold\nautoKillButton.TextSize = 18\nautoKillButton.Parent = controlPanel\n\n-- Status Label\nlocal statusLabel = Instance.new(\"TextLabel\")\nstatusLabel.Text = \"Status: IDLE\"\nstatusLabel.Size = UDim2.new(1, -20, 0, 20)\nstatusLabel.Position = UDim2.new(0, 10, 0, 165)\nstatusLabel.BackgroundTransparency = 1\nstatusLabel.TextColor3 = Color3.fromRGB(200, 200, 200)\nstatusLabel.Font = Enum.Font.SourceSans\nstatusLabel.TextSize = 14\nstatusLabel.TextXAlignment = Enum.TextXAlignment.Left\nstatusLabel.Parent = controlPanel\n\nlocal infoText = Instance.new(\"TextLabel\")\ninfoText.Text = \"Make sure you pull out the pistol you get\\non the civilian team and shoot it a bunch\\nof times before using.\"\ninfoText.Size = UDim2.new(1, -20, 0, 60)\ninfoText.Position = UDim2.new(0, 10, 0, 190)\ninfoText.BackgroundTransparency = 1\ninfoText.TextColor3 = Color3.fromRGB(200, 200, 200)\ninfoText.TextWrapped = true\ninfoText.TextXAlignment = Enum.TextXAlignment.Left\ninfoText.TextYAlignment = Enum.TextYAlignment.Top\ninfoText.Font = Enum.Font.SourceSansItalic\ninfoText.TextSize = 14\ninfoText.Parent = controlPanel\n\n-- Player list handling\nlocal playerButtons = {}\nlocal autoKillEnabled = false\nlocal autoKillConnection = nil\nlocal targetCache = {}\nlocal lastKillTime = {}\nlocal killCooldown = 0.3 -- Minimum time between kills on same target\n\nlocal function updateCanvas()\n\tscroll.CanvasSize = UDim2.new(0, 0, 0, layout.AbsoluteContentSize.Y + 10)\nend\n\n-- Reliable kill function with error handling\nlocal function killPlayer(name)\n\tif not name or name == \"\" then return false end\n\t\n\tlocal success, err = pcall(function()\n\t\tlocal target = workspace:FindFirstChild(name)\n\t\tif not target then return false end\n\t\t\n\t\tlocal Head = target:FindFirstChild(\"Head\")\n\t\tif not Head then return false end\n\t\t\n\t\tlocal humanoid = target:FindFirstChild(\"Humanoid\")\n\t\tif not humanoid then return false end\n\t\t\n\t\t-- Check if already dead\n\t\tif humanoid.Health <= 0 then return false end\n\t\t\n\t\t-- Cooldown check to prevent spam\n\t\tlocal currentTime = tick()\n\t\tif lastKillTime[name] and (currentTime - lastKillTime[name]) < killCooldown then\n\t\t\treturn false\n\t\tend\n\t\tlastKillTime[name] = currentTime\n\t\t\n\t\t-- Send 3 shots for reliability (not too many, not too few)\n\t\tfor i = 1, 3 do\n\t\t\tBulletEvent:FireServer(\"ApplyDamage\", {\n\t\t\t\tToolPriority = \"Primary\",\n\t\t\t\tBulletType = \"InstantProjectile\",\n\t\t\t\tBurstDelay = false,\n\t\t\t\tToolName = \"M17\",\n\t\t\t\tAutomatic = false,\n\t\t\t\tAmmo = 12,\n\t\t\t\tToolIconId = 18390745461,\n\t\t\t\tManualBulletReload = false,\n\t\t\t\tToolType = \"Weapon\",\n\t\t\t\tSounds = {\n\t\t\t\t\tMuzzleEffectsFolder = \"Rifle1\",\n\t\t\t\t\tReloadSound = {SoundId = \"rbxassetid://2178848067\", Volume = 0.5},\n\t\t\t\t\tEquipSound = {SoundId = \"rbxassetid://2178848067\", Volume = 0.5},\n\t\t\t\t\tShootSound = {SoundId = \"rbxassetid://3413044183\", Volume = 1},\n\t\t\t\t\tChamberEffectsFolder = \"Rifle1\"\n\t\t\t\t},\n\t\t\t\tBulletInfo = {\n\t\t\t\t\tBulletImpactHole = \"ImpactHole\",\n\t\t\t\t\tBulletsPerShot = 1,\n\t\t\t\t\tSpreadSuppress = 40,\n\t\t\t\t\tFireRate = 0.43,\n\t\t\t\t\tBulletImpactSmoke = \"BulletSmoke\",\n\t\t\t\t\tHeadMultiplier = 1.5,\n\t\t\t\t\tDamage = 11,\n\t\t\t\t\tBulletSpeed = 2000,\n\t\t\t\t\tRecoil = 0.15\n\t\t\t\t},\n\t\t\t\tWindUpTime = false,\n\t\t\t\tOTSCamera = true,\n\t\t\t\tAttachments = {},\n\t\t\t\tTrajectoryVisualization = false,\n\t\t\t\tAnimations = {\n\t\t\t\t\tShotgunRack = 18660122184,\n\t\t\t\t\tReloadAnimation = 18660037509,\n\t\t\t\t\tCustomRun = 18660740286,\n\t\t\t\t\tAimStart = 18659958529,\n\t\t\t\t\tShotgunReloadEnd = 18660125853,\n\t\t\t\t\tShotgunReloadStart = 18660117440,\n\t\t\t\t\tIdleAnimation = 18660031119,\n\t\t\t\t\tShootAnimation = 18660149380,\n\t\t\t\t\tAimIdle = 18659955595,\n\t\t\t\t\tIdleWithShieldAnimation = 9209313123,\n\t\t\t\t\tIdleSafetyAnimation = 18736425857,\n\t\t\t\t\tShotgunShellLoad = 18660136310\n\t\t\t\t}\n\t\t\t}, 8758447046, Head)\n\t\tend\n\t\t\n\t\treturn true\n\tend)\n\t\n\tif not success then\n\t\t-- Silently fail, don't crash the loop\n\t\treturn false\n\tend\n\treturn true\nend\n\nlocal function killall()\n\tlocal killed = 0\n\tfor _, v in pairs(workspace:GetChildren()) do\n\t\tif Players:FindFirstChild(v.Name) and v:FindFirstChild(\"Head\") then\n\t\t\tlocal humanoid = v:FindFirstChild(\"Humanoid\")\n\t\t\tif humanoid and humanoid.Health > 0 then\n\t\t\t\tif killPlayer(v.Name) then\n\t\t\t\t\tkilled = killed + 1\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\treturn killed\nend\n\n-- Update target cache for faster scanning\nlocal function updateTargetCache()\n\ttargetCache = {}\n\tfor _, v in pairs(workspace:GetChildren()) do\n\t\tif Players:FindFirstChild(v.Name) and v:FindFirstChild(\"Head\") then\n\t\t\tlocal humanoid = v:FindFirstChild(\"Humanoid\")\n\t\t\tif humanoid and humanoid.Health > 0 then\n\t\t\t\ttable.insert(targetCache, v)\n\t\t\tend\n\t\tend\n\tend\nend\n\n-- Start auto kill - RELIABLE version\nlocal function startAutoKill()\n\tif autoKillConnection then return end\n\t\n\tstatusLabel.Text = \"Status: SCANNING\"\n\tstatusLabel.TextColor3 = Color3.fromRGB(100, 255, 100)\n\t\n\t-- Use Heartbeat for speed, but with proper error handling\n\tautoKillConnection = RunService.Heartbeat:Connect(function()\n\t\tif not autoKillEnabled then return end\n\t\t\n\t\t-- Update cache every few frames to reduce lag\n\t\tif math.random(1, 3) == 1 then\n\t\t\tupdateTargetCache()\n\t\tend\n\t\t\n\t\t-- Kill any targets in cache\n\t\tlocal targetsToRemove = {}\n\t\tfor i, target in ipairs(targetCache) do\n\t\t\tif not autoKillEnabled then break end\n\t\t\t\n\t\t\t-- Check if target still exists and is alive\n\t\t\tif target and target.Parent and target:FindFirstChild(\"Head\") then\n\t\t\t\tlocal humanoid = target:FindFirstChild(\"Humanoid\")\n\t\t\t\tif humanoid and humanoid.Health > 0 then\n\t\t\t\t\t-- Try to kill\n\t\t\t\t\tlocal success = killPlayer(target.Name)\n\t\t\t\t\tif success then\n\t\t\t\t\t\tstatusLabel.Text = \"Status: KILLING \" .. target.Name\n\t\t\t\t\tend\n\t\t\t\telse\n\t\t\t\t\t-- Mark for removal from cache\n\t\t\t\t\ttable.insert(targetsToRemove, i)\n\t\t\t\tend\n\t\t\telse\n\t\t\t\t-- Mark for removal from cache\n\t\t\t\ttable.insert(targetsToRemove, i)\n\t\t\tend\n\t\t\t\n\t\t\t-- Small yield to prevent freezing\n\t\t\tif i % 3 == 0 then\n\t\t\t\tRunService.Heartbeat:Wait()\n\t\t\tend\n\t\tend\n\t\t\n\t\t-- Remove invalid targets from cache (in reverse order)\n\t\tfor i = #targetsToRemove, 1, -1 do\n\t\t\ttable.remove(targetCache, targetsToRemove[i])\n\t\tend\n\t\t\n\t\t-- Update status\n\t\tif autoKillEnabled and #targetCache > 0 then\n\t\t\tstatusLabel.Text = \"Status: ACTIVE (\" .. #targetCache .. \" targets)\"\n\t\telseif autoKillEnabled then\n\t\t\tstatusLabel.Text = \"Status: WAITING\"\n\t\tend\n\tend)\nend\n\nlocal function stopAutoKill()\n\tif autoKillConnection then\n\t\tautoKillConnection:Disconnect()\n\t\tautoKillConnection = nil\n\tend\n\ttargetCache = {}\n\tstatusLabel.Text = \"Status: IDLE\"\n\tstatusLabel.TextColor3 = Color3.fromRGB(200, 200, 200)\nend\n\n-- Toggle auto kill\nlocal function toggleAutoKill()\n\tautoKillEnabled = not autoKillEnabled\n\t\n\tif autoKillEnabled then\n\t\tautoKillButton.Text = \"Auto Kill: ON\"\n\t\tautoKillButton.BackgroundColor3 = Color3.fromRGB(30, 100, 30)\n\t\tupdateTargetCache()\n\t\tstartAutoKill()\n\telse\n\t\tautoKillButton.Text = \"Auto Kill: OFF\"\n\t\tautoKillButton.BackgroundColor3 = Color3.fromRGB(60, 30, 30)\n\t\tstopAutoKill()\n\tend\nend\n\nlocal function addPlayer(player)\n\tlocal button = Instance.new(\"TextButton\")\n\tbutton.Size = UDim2.new(1, -10, 0, 30)\n\tbutton.Text = player.Name\n\tbutton.BackgroundColor3 = Color3.fromRGB(60, 60, 60)\n\tbutton.TextColor3 = Color3.fromRGB(255, 255, 255)\n\tbutton.Font = Enum.Font.SourceSans\n\tbutton.TextSize = 18\n\tbutton.AutoButtonColor = true\n\tbutton.Parent = scroll\n\n\tbutton.MouseButton1Click:Connect(function()\n\t\tif setclipboard then\n\t\t\tsetclipboard(player.Name)\n\t\tend\n\tend)\n\n\tplayerButtons[player] = button\nend\n\nlocal function removePlayer(player)\n\tif playerButtons[player] then\n\t\tplayerButtons[player]:Destroy()\n\t\tplayerButtons[player] = nil\n\tend\n\t-- Remove from cache\n\tfor i, target in ipairs(targetCache) do\n\t\tif target and target.Name == player.Name then\n\t\t\ttable.remove(targetCache, i)\n\t\t\tbreak\n\t\tend\n\tend\nend\n\nlayout:GetPropertyChangedSignal(\"AbsoluteContentSize\"):Connect(updateCanvas)\n\n-- Initial player list\nfor _, plr in ipairs(Players:GetPlayers()) do\n\taddPlayer(plr)\nend\nupdateCanvas()\n\n-- Listen for joins/leaves\nPlayers.PlayerAdded:Connect(function(plr)\n\taddPlayer(plr)\n\tupdateCanvas()\nend)\n\nPlayers.PlayerRemoving:Connect(function(plr)\n\tremovePlayer(plr)\n\tupdateCanvas()\nend)\n\n-- Button actions\nkillButton.MouseButton1Click:Connect(function()\n\tlocal name = nameBox.Text\n\tif name and name ~= \"\" then\n\t\tkillPlayer(name)\n\tend\nend)\n\nkillAllButton.MouseButton1Click:Connect(function()\n\tlocal killed = killall()\n\tstatusLabel.Text = \"Status: KILLED \" .. killed .. \" players\"\n\ttask.wait(1)\n\tif autoKillEnabled then\n\t\tstatusLabel.Text = \"Status: ACTIVE (\" .. #targetCache .. \" targets)\"\n\telse\n\t\tstatusLabel.Text = \"Status: IDLE\"\n\tend\nend)\n\n-- Auto kill toggle\nautoKillButton.MouseButton1Click:Connect(toggleAutoKill)\n\n-- Clean up when script stops\nlocal function cleanup()\n\tstopAutoKill()\nend\n\n-- Keep script alive and reconnect if disconnected\nlocal function ensureRunning()\n\twhile true do\n\t\ttask.wait(5)\n\t\tif autoKillEnabled and not autoKillConnection then\n\t\t\tprint(\"Auto-kill disconnected, restarting...\")\n\t\t\tstartAutoKill()\n\t\tend\n\tend\nend\n\ngame:GetService(\"Players\").LocalPlayer:GetPropertyChangedSignal(\"Parent\"):Connect(function()\n\tif not localPlayer.Parent then\n\t\tcleanup()\n\tend\nend)\n\n-- Start watchdog\ntask.spawn(ensureRunning)\n\nprint(\"Auto Kill loaded! Click 'Auto Kill: OFF' to enable.\")\nprint(\"Script will automatically restart if it stops.\")\n")()
